describe('Async Data Fetching Does Not Block Initial Page Render', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should render initial page content before async data loads', () => {
    // Verify that the initial skeleton/placeholder content is visible immediately
    cy.get('[data-testid="page-header"]').should('be.visible');
    cy.get('[data-testid="initial-content"]').should('be.visible');

    // Verify that async data container exists but may not be loaded yet
    cy.get('[data-testid="async-data-container"]').should('exist');

    // Wait for async data to load and verify it appears
    cy.get('[data-testid="async-data-content"]', { timeout: 10000 }).should('be.visible');
    cy.get('[data-testid="async-data-content"]').should('contain', 'Loaded Data');
  });

  it('should handle multiple async requests without blocking render', () => {
    // Verify initial render happens immediately
    cy.get('[data-testid="page-title"]').should('be.visible');
    cy.get('[data-testid="loading-indicator"]').should('exist');

    // Verify first async data loads
    cy.get('[data-testid="user-data"]', { timeout: 8000 }).should('be.visible');
    cy.get('[data-testid="user-data"]').should('contain', 'User');

    // Verify second async data loads independently
    cy.get('[data-testid="posts-data"]', { timeout: 8000 }).should('be.visible');
    cy.get('[data-testid="posts-data"]').should('contain', 'Posts');

    // Verify page remains interactive during loading
    cy.get('[data-testid="interactive-button"]').should('be.enabled');
    cy.get('[data-testid="interactive-button"]').click();
    cy.get('[data-testid="button-result"]').should('be.visible');
  });

  it('should gracefully handle async data fetch errors without blocking page', () => {
    // Intercept and fail an async request
    cy.intercept('GET', '/api/data', { statusCode: 500, body: { error: 'Server Error' } });

    cy.visit('http://localhost:3000');

    // Verify initial content still renders
    cy.get('[data-testid="page-header"]').should('be.visible');

    // Verify error state is displayed for failed async data
    cy.get('[data-testid="error-message"]', { timeout: 8000 }).should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Error');

    // Verify page is still usable
    cy.get('[data-testid="retry-button"]').should('be.visible').and('be.enabled');
  });

  it('should render page with partial async data when some requests complete faster', () => {
    // Intercept requests with different delays
    cy.intercept('GET', '/api/fast-data', (req) => {
      req.reply((res) => {
        res.delay(500);
        res.send({ statusCode: 200, body: { data: 'Fast Data Loaded' } });
      });
    });

    cy.intercept('GET', '/api/slow-data', (req) => {
      req.reply((res) => {
        res.delay(3000);
        res.send({ statusCode: 200, body: { data: 'Slow Data Loaded' } });
      });
    });

    cy.visit('http://localhost:3000');

    // Verify initial render
    cy.get('[data-testid="page-content"]').should('be.visible');

    // Verify fast data loads first
    cy.get('[data-testid="fast-data"]', { timeout: 2000 }).should('be.visible');
    cy.get('[data-testid="fast-data"]').should('contain', 'Fast Data Loaded');

    // Verify slow data loads after
    cy.get('[data-testid="slow-data"]', { timeout: 5000 }).should('be.visible');
    cy.get('[data-testid="slow-data"]').should('contain', 'Slow Data Loaded');
  });
});
